<script lang="ts">
  import { untrack } from 'svelte';
  import { Sparkles, Footprints, Eye, Users, ChevronDown, ShieldCheck, Box } from 'lucide-svelte';
  import { tooltip } from './tooltip';
  import RefineSpacing from './RefineSpacing.svelte';
  import type { Photo,Pose,Contact,Support,InferredSupport,SideGuidance,Interaction } from './types';
  let {photo,poses,contacts=[],support=[],guidance=[],inferredSupport=[],pending=null,showOriginal=false,onOriginal,onChange,busy=false,hasEdits=false,canApply=true,onPreview,onPreviewSpacing,onApply,onCancel}:{photo:Photo;poses:Pose[];contacts?:Contact[];support?:Support[];guidance?:SideGuidance[];inferredSupport?:InferredSupport[];pending?:Interaction|null;showOriginal?:boolean;onOriginal:(value:boolean)=>void;onChange:()=>void;busy?:boolean;hasEdits?:boolean;canApply?:boolean;onPreview:(contacts:Contact[],support:Support[],guidance:SideGuidance[])=>void;onPreviewSpacing:(contacts:Contact[])=>void;onApply:()=>void;onCancel:()=>void}=$props();
  let person=$state(untrack(()=>poses[0]?.personId??1));
  let contactChanges=$state<Contact[]>(untrack(()=>JSON.parse(JSON.stringify(contacts))));
  let footChanges=$state<Support[]>(untrack(()=>JSON.parse(JSON.stringify(support))));
  let sideChanges=$state<SideGuidance[]>(untrack(()=>JSON.parse(JSON.stringify(guidance))));
  let replace=$state(false),showPoints=$state(false);
  const current=$derived(poses.find(p=>p.personId===person));
  const markers=$derived(current?.quality?.markers??[]);
  const regions=[{label:'Body',ids:['body']},{label:'Hands',ids:['l_hand','r_hand']},{label:'Feet',ids:['l_foot','r_foot']}];
  const states=[{id:'auto',label:'Auto',hint:'Use the support inferred from the image.'},{id:'flat',label:'Flat',hint:'The whole sole rests on the floor.'},{id:'toe',label:'On toes',hint:'Keep the heel raised and support the toes.'},{id:'heel',label:'On heel',hint:'Support the heel; the toes may lift.'},{id:'air',label:'In air',hint:'Do not pull this foot down to the floor.'}] as const;
  const presets=[{id:'keep',label:'Keep extraction',lean:0,hint:'Protect the accepted torso posture while refining details.'},{id:'upright',label:'Upright',lean:0,hint:'Gently bring the overall torso toward workspace vertical. Spinal curves remain articulated.'},{id:'forward',label:'Lean forward',lean:12,hint:'Prefer a forward torso lean relative to the reference camera, while keeping visible joints matched.'},{id:'backward',label:'Lean backward',lean:-12,hint:'Prefer a backward torso lean relative to the reference camera, within safe movement limits.'}] as const;
  const chosen=$derived(sideChanges.find(g=>g.personId===person)??{personId:person,preset:'keep' as const,strength:.35});
  const diagnostic=$derived(pending?.diagnostics.posture?.people.find(p=>p.personId===person));
  const closest=$derived(diagnostic?.limitedGuidance===true);
  const spacingPending=$derived(pending?.operation==='spacing');
  function side(preset:SideGuidance['preset'],strength=chosen.strength){onChange();sideChanges=[...sideChanges.filter(g=>g.personId!==person),{personId:person,preset,strength}];}
  const partLabel=(name:string)=>name.replace('l_','left ').replace('r_','right ').replace('palm','hand').replace('torso','body');
  function coverage(ids:string[]){const data=ids.map(id=>current?.quality?.regions?.[id]);return {count:data.reduce((n,p)=>n+(p?.count??0),0),expected:data.reduce((n,p)=>n+(p?.expected??0),0)};}
  function foot(side:'l'|'r',state:string){onChange();footChanges=footChanges.filter(p=>p.personId!==person||p.side!==side);if(state!=='auto')footChanges=[...footChanges,{personId:person,side,state:state as Support['state']}];}
  function footState(side:'l'|'r'){return footChanges.find(p=>p.personId===person&&p.side===side)?.state??'auto';}
  function inferred(side:'l'|'r'){return states.find(s=>s.id===inferredSupport.find(p=>p.personId===person&&p.side===side)?.state)?.label??'Uncertain';}
  function toggleContact(id:string,enabled:boolean){onChange();contactChanges=contactChanges.map(c=>c.id===id?{...c,enabled,confirmed:true}:c);}
</script>

<div class="refine-frame"><div class="refine-guide">
  <div class="auto-card"><span class="auto-icon"><Sparkles size={21}/></span><div><h3>Better details. Your posture.</h3><p>Fits detected hands, feet and contacts while protecting the torso. Preview changes before you apply them.</p></div><span class="local-badge">Local</span></div>
  {#if poses.length>1}<div class="person-tabs" role="group" aria-label="Person to inspect">{#each poses as p}<button class="secondary" class:active={person===p.personId} aria-pressed={person===p.personId} disabled={busy} onclick={()=>person=p.personId} use:tooltip={'Inspect detected details and set foot support for person '+p.personId+'. All participants are refined together.'}>Person {p.personId}</button>{/each}</div>{/if}
  <section class="evidence" aria-label="Detected detail coverage"><div class="section-heading"><h3>Detected details</h3><span>Person {person}</span></div><div class="coverage-grid">{#each regions as region}{@const points=coverage(region.ids)}<div class="coverage-card" use:tooltip={'Consistent '+region.label.toLowerCase()+' detections. Missing or ambiguous points are excluded from fitting.'}><span>{region.label}</span><strong>{points.expected?points.count+' / '+points.expected:'—'}</strong><small>{points.expected&&points.count===points.expected?'Detected':points.count?'Partial evidence':'Uncertain'}</small></div>{/each}</div><p class="hint">Hidden details remain estimates. Only reliable measurements guide the fit.</p></section>
  <details class="advanced side-guidance"><summary use:tooltip={'Optional per-person guidance for the unseen side posture. Does not add measured image evidence.'}><span><Box size={15}/> Side profile guidance <small>{chosen.preset==='keep'?'Optional':presets.find(p=>p.id===chosen.preset)?.label}</small></span><ChevronDown size={14}/></summary><p class="hint">Choose how the torso should look from the side. Feet are controlled separately below.</p>{#key person}<fieldset class="preset-grid"><legend class="sr-only">Torso from the side · Person {person}</legend>{#each presets as preset}<label class:chosen={chosen.preset===preset.id} use:tooltip={preset.hint}><input type="radio" name={'posture-'+person} checked={chosen.preset===preset.id} disabled={busy} onchange={()=>side(preset.id)}/><svg viewBox="0 0 60 58" aria-hidden="true"><path class="icon-floor" d="M8 53h44"/><path d="M30 51V36m0 0-9 14m9-14 9 14"/><g transform={'rotate('+preset.lean+' 30 36)'}><circle cx="30" cy="9" r="5"/><path d="M30 16v20m0-18-9 13m9-13 9 13"/></g>{#if preset.id==='keep'}<path class="icon-frame" d="M10 8V4h8m24 0h8v4M10 40v4h8m24 0h8v-4"/>{/if}</svg><span>{preset.label}</span></label>{/each}</fieldset>{/key}{#if chosen.preset!=='keep'}<label class="strength-label" for={'guidance-'+person}>Guidance strength <span>{Math.round(chosen.strength*100)}% · {chosen.strength<=.4?'Gentle':chosen.strength<=.7?'Moderate':'Strong'}</span></label><input class="strength" id={'guidance-'+person} type="range" min="10" max="100" step="5" value={chosen.strength*100} disabled={busy} oninput={e=>side(chosen.preset,Number(e.currentTarget.value)/100)} use:tooltip={'Start gently. Strong preferences can conflict with the photograph; the fit remains bounded.'}/>{/if}<p class="hint frame-note">Workspace preference · Camera gravity is unverified. This adds your intent, not a second measured view.</p></details>
  <section class="support-section"><div class="section-heading"><h3><Footprints size={16}/> Foot support</h3><span>Optional</span></div><p class="hint">Leave Auto, or choose how each foot meets the floor.</p>{#each ['l','r'] as side (person+'-'+side)}<fieldset class="foot-card"><legend>{side==='l'?'Left foot':'Right foot'} <span>Detected: {inferred(side as 'l'|'r')}</span></legend><div class="support-choices">{#each states as state}<label class:chosen={footState(side as 'l'|'r')===state.id} use:tooltip={state.hint}><input type="radio" name={'support-'+person+'-'+side} checked={footState(side as 'l'|'r')===state.id} disabled={busy} onchange={()=>foot(side as 'l'|'r',state.id)}/><span>{state.label}</span></label>{/each}</div></fieldset>{/each}</section>
  {#if poses.length>1}<details class="advanced"><summary use:tooltip={'Optionally confirm or turn off suggested contacts. Automatic fitting works without changing these.'}><span><Users size={15}/> Partner contacts <small>{contactChanges.filter(c=>c.enabled).length}</small></span><ChevronDown size={14}/></summary><p class="hint">Keep visible contacts enabled. Confirm only when the photograph is clear.</p>{#each contactChanges as c}<div class="contact-row"><label class="check"><input type="checkbox" checked={c.enabled} disabled={busy} onchange={e=>toggleContact(c.id,e.currentTarget.checked)} use:tooltip={'Include this suggested contact in the shared fit.'}/><span><strong>Person {c.personId} · {partLabel(c.part)}</strong><small>Touches person {c.otherId} · {partLabel(c.region)}</small></span></label><button class="text-button" disabled={busy||!c.enabled||c.confirmed} onclick={()=>toggleContact(c.id,true)} use:tooltip={c.confirmed?'You confirmed this contact.':'Give this visible contact more weight in the automatic fit.'}>{c.confirmed?'Confirmed':'Confirm'}</button></div>{:else}<p class="hint">No reliable contact was detected. Shared camera and floor fitting still apply.</p>{/each}</details>{/if}
  {#if poses.length>1}<RefineSpacing {pending} {busy} {showOriginal} {onOriginal} {canApply} available={poses.every(p=>!!p.referenceCamera)} onPreview={()=>onPreviewSpacing(contactChanges)}/>{/if}
  <details class="advanced"><summary use:tooltip={'Inspect extracted landmarks on a read-only reference. No point placement is required.'}><span><Eye size={15}/> Inspect image evidence</span><ChevronDown size={14}/></summary><label class="check"><input type="checkbox" bind:checked={showPoints} use:tooltip={'Show observed landmarks for this person on the original photograph.'}/> Show detected points</label><div class="evidence-photo"><img src={photo.url} alt="Original reference with optional detected landmark overlay"/>{#if showPoints}{#each markers as point}<span class="landmark" style:left={point.xy[0]/photo.width*100+'%'} style:top={point.xy[1]/photo.height*100+'%'}></span>{/each}{/if}</div><p class="hint">The fit uses the original-resolution image. This view is for inspection.</p></details>
  {#if hasEdits}<label class="check replace"><input type="checkbox" bind:checked={replace} disabled={busy} use:tooltip={'Save your current Pose studio edits as a local draft before replacement. Undo restores them.'}/><span>Save my edits as a snapshot, then refine</span></label>{/if}
  {#if pending&&!spacingPending}<section class="preview-summary" aria-label="Refinement preview"><div class="section-heading"><h3><Eye size={16}/> Preview · Not applied</h3><span>Person {person}</span></div><p class="hint">Inspect Side and Reference in the main preview. Apply keeps this result; Cancel restores your pose.</p>{#if diagnostic}<div class="posture-metrics"><span>Core change <strong>{diagnostic.coreRotationDegrees.toFixed(1)}°</strong></span><span>Depth change <strong>{diagnostic.coreDepthCm.toFixed(1)} cm</strong></span></div><p class="hint">{diagnostic.preset==='keep'?'Posture protected.':presets.find(p=>p.id===diagnostic.preset)?.label+' · User guidance applied.'} Guidance adds no observed landmarks.</p>{/if}{#if closest}<p class="hint frame-note">Closest safe preference. The reference or joint limits prevent a stronger change. Try gentler guidance or Keep extraction.</p>{/if}<label class="check compare"><input type="checkbox" checked={showOriginal} onchange={e=>onOriginal(e.currentTarget.checked)} use:tooltip={'Overlay the previously accepted mannequins as transparent ghosts, using the same renderer.'}/> Show original pose as a ghost</label></section>{/if}
  <p class="preserved"><ShieldCheck size={13}/> {(pending?.poses.find(p=>p.personId===person)??current)?.postureBaseline?.kind==='legacy-current'?'Legacy entry: preservation starts from its accepted pose.':'Your accepted pose stays safe until you choose Apply.'}</p>
  {#if !canApply}<p class="hint desktop-hint">Open the desktop app to run local refinement.</p>{/if}
  </div><div class="refine-actions"><button class="secondary" onclick={onCancel} disabled={busy} use:tooltip={'Close without changing the accepted pose.'}>Cancel</button>{#if pending}<button class="primary" disabled={!canApply||busy||hasEdits&&!replace||spacingPending&&!pending.diagnostics.spacing?.changed} onclick={onApply} use:tooltip={!canApply?'Apply is available in the desktop app.':spacingPending&&!pending.diagnostics.spacing?.changed?'The current layout was retained. There is no spacing change to apply.':hasEdits&&!replace?'Select the snapshot option before replacing your edits.':'Apply the inspected candidate as one undoable operation.'}><ShieldCheck size={15}/> {spacingPending?'Apply spacing':'Apply match'}</button>{:else}<button class="primary" disabled={!canApply||busy} onclick={()=>onPreview(contactChanges,footChanges,sideChanges)} use:tooltip={!canApply?'Automatic refinement runs in the desktop app.':'Preview a local fit of detected details and optional side guidance. The accepted pose is not replaced.'}><Sparkles size={15}/>{busy?'Fitting…':'Preview match'}</button>{/if}</div>
</div>
<style>
  .refine-frame{display:flex;flex-direction:column;flex:1;min-height:0}.refine-guide{display:grid;align-content:start;grid-auto-rows:max-content;gap:18px;flex:1;min-height:0;overflow-y:auto;overscroll-behavior:contain;padding:20px 22px;scrollbar-width:thin;scrollbar-color:var(--line) transparent}.auto-card{position:relative;display:flex;align-items:flex-start;gap:12px;padding:16px;border:1px solid color-mix(in srgb,var(--accent) 30%,var(--line));border-radius:14px;background:linear-gradient(135deg,color-mix(in srgb,var(--accent) 9%,var(--panel)),var(--panel))}.auto-icon{color:var(--accent);padding-top:3px}.auto-card h3{font-size:13px;margin:0 32px 6px 0}.auto-card p,.hint{font-size:11px;line-height:1.65;color:var(--muted);margin:0}.local-badge{position:absolute;right:12px;top:13px;font-size:9px;color:var(--accent)}.person-tabs{display:flex;gap:6px;flex-wrap:wrap}.person-tabs button{flex:1;font-size:11px;justify-content:center}.person-tabs button.active{border-color:var(--accent);background:color-mix(in srgb,var(--accent) 10%,var(--panel));color:var(--accent)}.section-heading{display:flex;align-items:center;justify-content:space-between;margin-bottom:9px}.section-heading h3{display:flex;align-items:center;gap:7px;font-size:12px;margin:0}.section-heading>span{font-size:10px;color:var(--muted)}.coverage-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:8px}.coverage-card{display:grid;gap:5px;padding:12px;border:1px solid var(--line);border-radius:10px}.coverage-card span,.coverage-card small{font-size:10px;color:var(--muted)}.coverage-card strong{font-size:17px;font-weight:600;font-variant-numeric:tabular-nums}.evidence .hint{margin-top:9px}.foot-card{border:1px solid var(--line);border-radius:10px;padding:10px;margin:12px 0 0;min-width:0}.foot-card legend{font-size:11px;font-weight:600;padding:0 4px}.foot-card legend span{font-size:9px;font-weight:400;color:var(--muted);margin-left:8px}.support-choices{display:flex;gap:4px;flex-wrap:wrap}.support-choices label{display:flex;align-items:center;justify-content:center;gap:4px;flex:1;padding:7px 5px;min-width:45px;border:1px solid transparent;border-radius:6px;font-size:10px;color:var(--muted);cursor:pointer}.support-choices input{width:11px;height:11px;margin:0;accent-color:var(--accent)}.support-choices .chosen{color:var(--accent);border-color:color-mix(in srgb,var(--accent) 40%,var(--line));background:color-mix(in srgb,var(--accent) 9%,var(--panel))}.support-choices label:focus-within{outline:2px solid var(--accent);outline-offset:2px}.advanced{border:1px solid var(--line);border-radius:10px;padding:12px}.advanced summary{display:flex;align-items:center;justify-content:space-between;cursor:pointer;font-size:11px;font-weight:600;list-style:none}.advanced summary::-webkit-details-marker{display:none}.advanced summary span{display:flex;align-items:center;gap:7px}.advanced summary small{color:var(--accent)}.advanced[open] summary{margin-bottom:12px}.advanced[open] summary>:global(svg){transform:rotate(180deg)}.check{display:flex;align-items:center;gap:9px;font-size:11px;line-height:1.5}.check input{accent-color:var(--accent)}.contact-row{display:flex;align-items:center;gap:8px;justify-content:space-between;padding:12px 0;border-bottom:1px solid var(--line)}.contact-row:last-child{border-bottom:0;padding-bottom:0}.contact-row strong,.contact-row small{display:block;font-size:10px}.contact-row small{color:var(--muted);margin-top:3px}.contact-row button{font-size:10px;padding:4px}.evidence-photo{position:relative;margin:12px 0;line-height:0}.evidence-photo img{width:100%;border-radius:8px}.landmark{position:absolute;width:5px;height:5px;background:var(--accent);border:1px solid var(--panel);border-radius:50%;transform:translate(-50%,-50%);pointer-events:none}.replace{padding:12px;border:1px solid var(--line);border-radius:10px}.preserved{display:flex;align-items:flex-start;gap:6px;font-size:10px;line-height:1.5;color:var(--muted);margin:0}.preserved :global(svg){flex-shrink:0}.desktop-hint{color:var(--accent)}.refine-actions{flex-shrink:0;display:flex;justify-content:flex-end;gap:8px;padding:14px 22px 20px;background:var(--panel);border-top:1px solid var(--line);box-shadow:0 -8px 16px var(--panel)}

  .preset-grid{display:grid;grid-template-columns:repeat(2,1fr);gap:8px;padding:0;margin:12px 0;border:0;min-width:0}.preset-grid label{position:relative;display:grid;justify-items:center;gap:7px;padding:10px;border:1px solid var(--line);border-radius:9px;color:var(--muted);cursor:pointer;font-size:10px}.preset-grid input{position:absolute;top:9px;left:9px;width:11px;height:11px;margin:0;accent-color:var(--accent)}.preset-grid svg{width:60px;height:58px;fill:none;stroke:currentColor;stroke-width:2.5;stroke-linecap:round;stroke-linejoin:round}.preset-grid svg circle{fill:currentColor;stroke:none}.preset-grid .icon-floor{opacity:.25;stroke-width:1}.preset-grid .icon-frame{opacity:.6;stroke-width:1.2}.preset-grid .chosen{color:var(--accent);border-color:var(--accent);background:color-mix(in srgb,var(--accent) 8%,var(--panel))}.preset-grid label:focus-within{outline:2px solid var(--accent);outline-offset:2px}.strength-label{display:flex;align-items:center;justify-content:space-between;font-size:11px;margin-top:16px}.strength-label span{font-size:10px;color:var(--muted);font-variant-numeric:tabular-nums}.strength{width:100%;accent-color:var(--accent);margin:12px 0}.frame-note{margin-top:12px}.preview-summary{border:1px solid color-mix(in srgb,var(--accent) 50%,var(--line));border-radius:10px;padding:13px;background:color-mix(in srgb,var(--accent) 5%,var(--panel))}.posture-metrics{display:flex;gap:18px;margin:12px 0;font-size:10px;color:var(--muted)}.posture-metrics strong{display:block;color:var(--text);font-size:14px;font-variant-numeric:tabular-nums;margin-top:4px}.compare{margin-top:13px}
</style>








